/* ============ AETHERIA — mobile-first UI ============ */
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;user-select:none;-webkit-user-select:none}
html,body{width:100%;height:100%;overflow:hidden;background:#07070d;touch-action:none;overscroll-behavior:none}
body{font-family:'Trebuchet MS','Segoe UI',Verdana,sans-serif;color:#e8e2d0}
#app{position:fixed;inset:0}
#game{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges;background:#07070d}
.hidden{display:none!important}

/* ---------- HUD ---------- */
#hud{position:absolute;inset:0;pointer-events:none}
#topbar{position:absolute;top:calc(4px + env(safe-area-inset-top));left:6px;right:6px;display:flex;align-items:flex-start;gap:6px;pointer-events:none}
#bars{flex:1;max-width:46%;min-width:150px}
.bar{position:relative;height:13px;background:#11131d;border:1px solid #3a3f55;border-radius:7px;margin-bottom:3px;overflow:hidden}
.bar>div{height:100%;border-radius:6px;transition:width .15s}
.bar.hp>div{background:linear-gradient(#ff5a5a,#b32222)}
.bar.mp>div{background:linear-gradient(#5aa0ff,#223fb3)}
.bar.xp>div{background:linear-gradient(#ffd75a,#c99312)}
.bar span{position:absolute;inset:0;font-size:9px;line-height:12px;text-align:center;color:#fff;text-shadow:1px 1px 0 #000;font-weight:bold}
#curex{margin-left:auto;text-align:right;font-size:11px;line-height:14px;text-shadow:1px 1px 0 #000;white-space:nowrap}
#curex .g{color:#ffd75a}#curex .m{color:#7ac8ff}#curex .z{color:#bbb}
#minimap{width:92px;height:92px;border:2px solid #3a3f55;border-radius:10px;background:#10121a;pointer-events:auto}
#zoneTag{position:absolute;top:calc(106px + env(safe-area-inset-top));left:8px;font-size:12px;font-weight:bold;color:#ffdf8a;text-shadow:1px 1px 2px #000;pointer-events:none;text-align:left}

#menuRow{position:absolute;top:calc(4px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);display:flex;gap:5px;pointer-events:auto}
.mbtn{width:44px;height:40px;background:rgba(20,24,38,.85);border:1px solid #4a5078;border-radius:9px;color:#ffdf8a;font-size:9px;font-weight:bold;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;pointer-events:auto}
.mbtn i{font-size:15px;font-style:normal;line-height:1}
.mbtn .dot{position:absolute;margin-top:-30px;margin-left:26px;width:9px;height:9px;background:#ff4040;border-radius:50%;border:1px solid #000}
.mbtn{position:relative}

#joy{position:absolute;left:18px;bottom:calc(18px + env(safe-area-inset-bottom));width:124px;height:124px;border-radius:50%;background:rgba(18,20,32,.5);border:2px solid rgba(90,100,140,.55);pointer-events:auto}
#joyKnob{position:absolute;left:41px;top:41px;width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#9fb2e8,#3f4a78);border:2px solid #0a0c14}
#btns{position:absolute;right:10px;bottom:calc(10px + env(safe-area-inset-bottom));width:190px;height:210px;pointer-events:none}
.abtn{position:absolute;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(90,100,150,.95),rgba(25,28,48,.95));border:2px solid #5a6490;color:#fff;font-weight:bold;text-align:center;pointer-events:auto;font-size:10px;line-height:1.05;display:flex;flex-direction:column;align-items:center;justify-content:center;text-shadow:1px 1px 1px #000}
.abtn:active{filter:brightness(1.5)}
.abtn small{font-size:8px;font-weight:normal;opacity:.85}
#bAtk{right:120px;bottom:60px;width:64px;height:64px;font-size:11px;border-color:#c85a3a;background:radial-gradient(circle at 35% 30%,rgba(200,90,60,.95),rgba(80,25,15,.95))}
#bSkill{right:48px;bottom:96px;width:58px;height:58px;border-color:#7a5ac8}
#bAuto{right:120px;bottom:135px;width:44px;height:44px;border-color:#3aa87a;font-size:9px}
#bAuto.on{border-color:#7affc8;background:radial-gradient(circle at 35% 30%,rgba(60,180,120,.95),rgba(10,60,40,.95))}
#bHpPot{right:52px;bottom:28px;width:46px;height:46px;border-color:#b33}
#bMpPot{right:4px;bottom:60px;width:46px;height:46px;border-color:#33a}
#bInter{right:4px;bottom:150px;width:52px;height:52px;border-color:#d8b13a;font-size:10px}
.badge{position:absolute;top:-3px;right:-3px;background:#ffd75a;color:#000;border-radius:8px;font-size:9px;padding:0 3px;border:1px solid #000}

/* ---------- toasts & floating ---------- */
#toasts{position:absolute;left:50%;top:24%;transform:translateX(-50%);width:min(80vw,340px);pointer-events:none;z-index:60}
.toast{background:rgba(12,14,24,.92);border:1px solid #6a7298;border-radius:10px;padding:8px 12px;margin-bottom:6px;font-size:12px;text-align:center;animation:tfade 3s forwards}
.toast.good{border-color:#4fae6f}.toast.bad{border-color:#c05050}.toast.gold{border-color:#d8b13a}
@keyframes tfade{0%{opacity:0;transform:translateY(-8px)}10%{opacity:1;transform:none}80%{opacity:1}100%{opacity:0}}

/* ---------- panels ---------- */
#panels{position:absolute;inset:0;pointer-events:none;z-index:40}
.panel{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(96vw,560px);max-height:88vh;background:#12141f;border:2px solid #4a5078;border-radius:14px;pointer-events:auto;display:flex;flex-direction:column;box-shadow:0 10px 40px rgba(0,0,0,.7)}
.panel .phead{display:flex;align-items:center;padding:9px 12px;border-bottom:1px solid #33384f;flex:0 0 auto}
.panel .phead h3{font-size:14px;color:#ffdf8a;letter-spacing:1px}
.panel .phead .sp{flex:1}
.pclose{width:32px;height:32px;border-radius:8px;background:#2a2e44;border:1px solid #4a5078;color:#ff9a9a;font-size:15px;font-weight:bold}
.pbody{flex:1;overflow-y:auto;padding:10px;overscroll-behavior:contain}
.tabs{display:flex;gap:4px;padding:8px 10px 0;flex-wrap:wrap;flex:0 0 auto}
.tab{padding:6px 12px;background:#1c2030;border:1px solid #3a3f55;border-radius:8px 8px 0 0;font-size:11px;font-weight:bold;color:#9aa3c8}
.tab.on{background:#31365a;color:#ffdf8a}
.row{display:flex;align-items:center;gap:8px;padding:7px 6px;border-bottom:1px solid #23273b;font-size:12px}
.row .grow{flex:1;min-width:0}
.row .name{font-weight:bold;color:#fff}
.row .sub{font-size:10px;color:#9aa3c8}
.btn{padding:7px 12px;background:linear-gradient(#3a4160,#252a42);border:1px solid #6a7298;border-radius:9px;color:#ffe8b0;font-weight:bold;font-size:11px}
.btn:active{filter:brightness(1.4)}
.btn.small{padding:5px 9px;font-size:10px}
.btn.gold{border-color:#d8b13a;color:#ffd75a}.btn.gem{border-color:#7ac8ff;color:#a8e0ff}
.btn.dis{opacity:.45;pointer-events:none}
.btn.danger{border-color:#a04040;color:#ff9a9a}
.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}
.cell{position:relative;aspect-ratio:1;background:#181b2a;border:1px solid #3a3f55;border-radius:9px;display:flex;align-items:center;justify-content:center;overflow:hidden}
.cell canvas{width:82%;height:82%;image-rendering:pixelated}
.cell .n{position:absolute;bottom:1px;right:3px;font-size:10px;font-weight:bold;color:#fff;text-shadow:1px 1px 0 #000}
.cell.sel{border-color:#ffdf8a;box-shadow:0 0 6px #ffdf8a}
.statline{font-size:11px;padding:5px 8px;background:#1a1d2e;border-radius:8px;margin-bottom:8px;line-height:1.5}
.statline b{color:#ffd75a}
.qtf{color:#ffd75a;font-weight:bold}
.slotline{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:10px}
.eqcell{position:relative;aspect-ratio:1;background:#181b2a;border:1px solid #3a3f55;border-radius:9px;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:9px;color:#8a90b8;text-align:center}
.eqcell canvas{width:60%;height:60%;image-rendering:pixelated}
.eqcell.filled{border-color:#6a7298}
.eqcell .sn{position:absolute;top:2px;left:3px;font-size:8px;letter-spacing:.4px}
.proj{display:flex;gap:8px;align-items:center;margin-bottom:8px}
.proj canvas{width:52px;height:52px;background:#181b2a;border:1px solid #3a3f55;border-radius:9px;image-rendering:pixelated}
.note{font-size:10px;color:#8a90b8;padding:6px 8px;background:#1a1d2e;border-radius:8px;margin:6px 0;line-height:1.5}
input[type=text]{width:100%;padding:9px 10px;background:#0e1018;border:1px solid #4a5078;border-radius:9px;color:#fff;font-size:14px;outline:none}
select{background:#0e1018;border:1px solid #4a5078;color:#fff;border-radius:8px;padding:6px;font-size:12px}
.kv{display:flex;justify-content:space-between;font-size:11px;padding:3px 0}
.kv b{color:#ffd75a}

/* ---------- character creation ---------- */
#create{position:absolute;inset:0;z-index:80;background:radial-gradient(120% 90% at 50% 0%,#232a4e 0%,#0c0d19 60%,#07070d 100%);display:flex;flex-direction:column;align-items:center;overflow-y:auto;padding:calc(10px + env(safe-area-inset-top)) 12px 30px}
#create h1{font-size:30px;letter-spacing:8px;color:#ffdf8a;text-shadow:0 0 18px rgba(255,200,80,.45),2px 2px 0 #000;margin:6px 0 2px;text-align:center}
#create .slog{font-size:11px;color:#9aa3c8;letter-spacing:2px;margin-bottom:10px}
.cstep{margin:0 auto;width:min(92vw,460px)}
#prevWrap{display:flex;justify-content:center;margin:8px 0}
#prevWrap canvas{width:190px;height:230px;background:rgba(10,12,22,.65);border:2px solid #4a5078;border-radius:14px;image-rendering:pixelated}
.optRow{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:8px 0}
.chip{padding:9px 14px;background:#171a2a;border:2px solid #3a3f55;border-radius:11px;font-size:12px;font-weight:bold;color:#cdd3ee;text-align:center}
.chip.on{border-color:#ffdf8a;color:#ffdf8a;background:#2a2438;box-shadow:0 0 10px rgba(255,215,90,.3)}
.chip small{display:block;font-weight:normal;color:#8a90b8;font-size:9px;margin-top:2px}
.swatch{width:30px;height:30px;border-radius:50%;border:2px solid #3a3f55}
.swatch.on{border-color:#fff;box-shadow:0 0 8px #fff}
.navRow{display:flex;gap:10px;justify-content:center;margin:14px 0}
.bigbtn{padding:12px 30px;font-size:14px;border-radius:12px;background:linear-gradient(#8a5a20,#5a3608);border:2px solid #ffd75a;color:#ffe8b0;letter-spacing:1px}
.bigbtn:disabled{opacity:.4}
.clsCard{width:120px;padding:10px 6px;background:#141726;border:2px solid #3a3f55;border-radius:12px;text-align:center}
.clsCard.on{border-color:#ffdf8a}
.clsCard canvas{width:70px;height:86px;image-rendering:pixelated}
.clsCard b{font-size:12px;color:#ffdf8a}
.clsCard p{font-size:9px;color:#9aa3c8;line-height:1.3;margin-top:3px}

/* misc */
#errlog{position:absolute;left:4px;bottom:2px;max-width:96vw;font:9px monospace;color:#ff8;white-space:pre-wrap;z-index:200;pointer-events:none;opacity:.85}
.fx-crit{color:#ffdf5a;font-weight:bold}
</style>

/* ============ AETHERIA — config & constants ============ */
"use strict";
var CONFIG = {
  // ---- economy: all prices configurable here ----
  prices: {
    potionHP:     60,     // Gold, minor healing potion
    potionHPBig:  180,    // Gold, greater healing potion
    potionMP:     50,     // Gold, mana potion
    teleport:     80,     // Gold per teleport to an unlocked town/region
    craftFee:     50,     // Gold, blacksmith general craft fee
    fusionFee:    {common:20, grey:40, green:80, blue:160, purple:320, legendary:640, mythic:1280, divine:9999},
    legendaryGold:5000,   // Gold for a legendary craft
    storageUpg:   400,    // Gold, expand stash by 12 slots
    marketFeePct: 0.05,   // 5% cut on sold listings
  },
  // ---- direct drop rarities (only these ever drop; always T3) ----
  drops: { common: 0.60, grey: 0.25, green: 0.10, blue: 0.05 },
  equipDropChance: 0.16,   // chance a normal mob drops a piece of gear
  matDropChance:   0.35,
  critCap: 0.50,           // critical chance hard cap (50%)
  mobRespawnSec: 14,
  bossRespawnSec: 90,
  // ---- progression ----
  xpBase: 90, xpGrowth: 1.30,
  statGrowth: { hp: 16, mp: 7, atk: 2.2, def: 1.4 },
  skillUpCost: lv => Math.round(200 * Math.pow(1.7, lv - 1)), // gold, skill lv 1->10
  // ---- tier/rarity multipliers ----
  tierMult: { 3: 1.00, 2: 1.20, 1: 1.45 }, // fusion improves stats
  rares: {
    common:    { name: "Common",    col: "#e8e8e8", mult: 1.00, bonus: 0 },
    grey:      { name: "Grey",      col: "#b0b4bd", mult: 1.10, bonus: 0 },
    green:     { name: "Green",     col: "#66d866", mult: 1.22, bonus: 1 },
    blue:      { name: "Blue",      col: "#58a8ff", mult: 1.38, bonus: 2 },
    purple:    { name: "Purple",    col: "#c05cff", mult: 1.65, bonus: 2 },
    legendary: { name: "Legendary", col: "#ffa02e", mult: 2.10, bonus: 3 },
    mythic:    { name: "Mythic",    col: "#ff4fd8", mult: 2.75, bonus: 3 },
    divine:    { name: "Divine",    col: "#ffe680", mult: 3.50, bonus: 4 },
  },
  // ---- rendering ----
  TW: 64, TH: 32,          // isometric tile size
  MAXDPR: 1.5,
};
var CRITCAP = CONFIG.critCap;

/* ============ AETHERIA — game data ============ */
"use strict";
var TW = CONFIG.TW, TH = CONFIG.TH;

const Data = (() => {
  /* ---------------- utility: seeded RNG ---------------- */
  function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
  function strSeed(s){let h=1779033703;for(let i=0;i<s.length;i++){h=Math.imul(h^s.charCodeAt(i),3432918353);h=h<<13|h>>>19}return h>>>0}
  const rngOf = seed => mulberry32(strSeed(seed));
  const pick = (r, arr) => arr[Math.floor(r()*arr.length)];
  const ri = (r, a, b) => a + Math.floor(r()*(b-a+1));

  /* ---------------- rarity chain ---------------- */
  const RAR_ORDER = ["common","grey","green","blue","purple","legendary","mythic","divine"];
  const nextRar = q => { const i = RAR_ORDER.indexOf(q); return i >= RAR_ORDER.length-1 ? null : RAR_ORDER[i+1]; };

  /* ---------------- classes ---------------- */
  const CLASSES = {
    warrior: { id:"warrior", name:"Warrior", shortName:"Warrior",
      desc:"A strong melee fighter with heavy armor and sweeping steel.",
      weapon:"Great Sword", offhand:"War Shield",
      base:{ hp:260, mp:70, atk:15, def:11, crit:.05, spd:3.1, atkRange:1.1, atkCd:.85 },
      skill:{ name:"Whirlwind Slash", desc:"Spin in a wide arc, hitting all enemies around you.",
        mult:2.6, perLv:.22, mp:22, cd:6, kind:"aoeSelf", radius:2.3, fx:"slash" } },
    mage: { id:"mage", name:"Mage", shortName:"Mage",
      desc:"A powerful spellcaster firing arcane bolts and raining fire.",
      weapon:"Rune Staff", offhand:"Grimoire",
      base:{ hp:170, mp:150, atk:18, def:6, crit:.07, spd:3.1, atkRange:5.5, atkCd:.95 },
      skill:{ name:"Meteor Fall", desc:"Call a meteor on the nearest enemy group.",
        mult:3.2, perLv:.28, mp:38, cd:7, kind:"aoeBolt", radius:2.4, fx:"meteor" } },
    assassin: { id:"assassin", name:"Assassin", shortName:"Assassin",
      desc:"A blade in the dark — fast strikes and deadly critical hits.",
      weapon:"Fang Daggers", offhand:"Poison Vial",
      base:{ hp:200, mp:95, atk:13, def:7, crit:.18, spd:3.6, atkRange:0.95, atkCd:.55 },
      skill:{ name:"Shadow Flurry", desc:"Vanish and strike the nearest foe 5 times, each can crit.",
        mult:.9, hits:5, perLv:.12, mp:28, cd:5, kind:"flurry", fx:"shadow" } },
  };

  /* ---------------- factions ---------------- */
  const FACTIONS = {
    angel: { id:"angel", name:"Angels", tag:"Celestial host of the Dawn.", bonus:"Fallen-sky blessing: +8% DEF, and radiant wings.",
      defx:1.08, wingDefault:"wng_angel", col:"#e8f4ff" },
    demon: { id:"demon", name:"Demons", tag:"Devil-blooded legions of the Ash.", bonus:"Ashen fury: +8% ATK and leathern wings.",
      atkx:1.08, wingDefault:"wng_demon", col:"#ffd6e0" },
  };

  /* ---------------- appearance ---------------- */
  const HAIRSTYLES = ["Short","Bob","Long","Ponytail","Mohawk"];
  const HAIRCOLORS = [
    {id:0,name:"Soot Black", c:"#2a2630"},{id:1,name:"Chestnut", c:"#6b4226"},
    {id:2,name:"Golden", c:"#d8a833"},{id:3,name:"Silver", c:"#c9ccd6"},
    {id:4,name:"Crimson", c:"#a83030"},{id:5,name:"Forest Green", c:"#3f7a4f"},
    {id:6,name:"Sky Blue", c:"#4f86c8"},{id:7,name:"Snow White", c:"#e8e8f0"}];
  const EYECOLORS = [
    {id:0,name:"Brown", c:"#7a4a26"},{id:1,name:"Hazel", c:"#b8862a"},
    {id:2,name:"Green", c:"#3fa860"},{id:3,name:"Blue", c:"#4a86d8"},
    {id:4,name:"Violet", c:"#9a5ad0"},{id:5,name:"Crimson", c:"#d04a4a"},
    {id:6,name:"Gold", c:"#d8a833"},{id:7,name:"Grey", c:"#9aa0aa"}];
  // outfit palettes per class: 3 starting outfits
  const OUTFITS = {
    warrior:[ {name:"Recruit Kit",  a:"#8a3030", b:"#5a5f6e"},   // red tunic + steel
              {name:"Traveler Kit", a:"#3f6e3f", b:"#6e5a3f"},   // green + leather
              {name:"Guard Kit",    a:"#2f4a7a", b:"#8a8fa0"} ],
    mage:   [ {name:"Apprentice Robe", a:"#2f3f7a", b:"#c8b04f"},
              {name:"Wanderer Robe",   a:"#3f7a5f", b:"#d0784f"},
              {name:"Starweave Robe",  a:"#5a3f7a", b:"#6fc8d8"} ],
    assassin:[ {name:"Scout Wraps",    a:"#3a3f4a", b:"#7a6a4a"},
               {name:"Nightcloaks",    a:"#1f2230", b:"#5a2f3f"},
               {name:"Swampweave",     a:"#2f4a3a", b:"#6a7a4a"} ],
  };
  const COSTUMES = [ {id:"cust_sun", name:"Summer Breeze", unlock:"shop", pal:{a:"#e8a86a", b:"#f8e8c8"} },
                     {id:"cust_noble", name:"Noble Regalia", unlock:"shop", pal:{a:"#7a2f5a", b:"#ffd75a"} },
                     {id:"cust_void", name:"Void-touched", unlock:"shop", pal:{a:"#1a1428", b:"#7a4fc8"} } ];

  /* ---------------- world maps ---------------- */
  const SLOTS = ["head","chest","legs","boots","gloves","weapon","offhand","amulet","ring"];
  const SLOTNAME = { head:"Headgear", chest:"Chest", legs:"Legs", boots:"Boots", gloves:"Gloves",
                     weapon:"Weapon", offhand:"Off-hand", amulet:"Amulet", ring:"Ring" };
  const ILVLS = [1,10,20,30,40,50,60,70];
  const IPRE = ["Worn","Trainee's","Iron","Steel","Silver","Mithril","Draconic","Eternal"];

  const WEAPONS = { warrior:"Great Sword", mage:"Rune Staff", assassin:"Fang Daggers" };
  const OFFHANDS = { warrior:"War Shield", mage:"Grimoire", assassin:"Poison Vial" };
  const ARMOR = {
    warrior:{ head:"Helm", chest:"Cuirass", legs:"Greaves", boots:"Sabatons", gloves:"Gauntlets" },
    mage:   { head:"Circlet", chest:"Robe", legs:"Silk Wrap", boots:"Slippers", gloves:"Sleeves" },
    assassin:{ head:"Hood", chest:"Vest", legs:"Legwraps", boots:"Striders", gloves:"Bracers" } };

  const ITEMS = {};
  function addTpl(t){ ITEMS[t.id] = t; }
  function statsFor(slot, cls, ilvl){
    switch(slot){
      case "weapon": return { atk: +(7 + ilvl*2.5).toFixed(1), crit: cls==="assassin"? 4 : 2 };
      case "offhand":{ const s = { def: +(2 + ilvl*0.9).toFixed(1) };
        if(cls==="mage") s.mp = +(10 + ilvl*1.1).toFixed(1);
        if(cls==="assassin") s.atk = +(2 + ilvl*0.5).toFixed(1);
        return s; }
      case "head":  return { def: +(2 + ilvl*0.8).toFixed(1), mp: cls==="mage"?+(6+ilvl*0.5).toFixed(1):0 };
      case "chest": return { def: +(3 + ilvl*1.1).toFixed(1), hp: +(18 + ilvl*3.2).toFixed(1) };
      case "legs":  return { def: +(2 + ilvl*0.8).toFixed(1), hp: +(12 + ilvl*2.2).toFixed(1) };
      case "boots": return { def: +(2 + ilvl*0.6).toFixed(1), spd: .10 };
      case "gloves":return { atk: +(2 + ilvl*0.7).toFixed(1), def: +(1 + ilvl*0.4).toFixed(1) };
      case "amulet":return {};
      case "ring":  return { crit: +(1 + ilvl*0.06).toFixed(1) };
    }
  }
  for(const cls of ["warrior","mage","assassin"]) for(let i=0;i<ILVLS.length;i++){
    const ilvl=ILVLS[i], pre=IPRE[i];
    for(const slot of SLOTS){
      let name;
      if(slot==="weapon") name = pre+" "+WEAPONS[cls];
      else if(slot==="offhand") name = pre+" "+OFFHANDS[cls];
      else name = pre+" "+ARMOR[cls][slot];
      addTpl({ id:`${slot}_${cls}_${ilvl}`, slot, cls, ilvl, name, stats: statsFor(slot,cls,ilvl) });
    }
  }

