    } else if(slot === "offhand"){
      if(cls === "mage"){ rectBook(g); } else if(cls === "assassin"){ px(g, 16, 10, 16, 28, "#4f8f4a"); px(g, 20, 14, 8, 6, "#e8e8e8"); px(g, 19, 36, 10, 6, "#3a2a2a"); }
