      `<div class="grow"><div class="name">${u.name}</div><div class="sub">${u.heal?"Restores "+u.heal+" HP":"Restores "+u.mana+" MP"} · owned ${countStack(id)}</div></div>`,
      `<button class="btn small gold" data-bu="${id}">${u.price}g</button>`));
